#include "sprite_row_cases.h"
#include <cstdio>
#include <stdexcept>
namespace {unsigned checks;void check(bool value,const char* why){++checks;if(!value)throw std::runtime_error(why);}}
int main(){using namespace Snatcher;try{SceneRenderer renderer;std::string error;check(spriteRowRenderer(renderer,error),"authored graphics owners");
 for(unsigned index=0;index<10;++index){SceneImage image;check(renderer.render(spriteRowCase(index),kSceneRGB888,image,error),error.c_str());check(image.indexed.size()==57344&&image.rgb.size()==172032,"full unmasked frame extent");for(unsigned y=0;y<224;++y)for(unsigned x=0;x<256;++x){unsigned expected=0;if(y>=64&&y<72){if((index==0&&x<128)||(index==8&&x<120))expected=1;else if(index==3&&x>=80&&x<88)expected=1;else if(index==4&&x>=80&&x<88)expected=2;else if(index==6&&x>=80&&x<96)expected=x<88?1:2;}check(image.indexed[y*256+x]==expected,"source-qualified row admission pixel");uint8_t r,g,b;check(sceneColor(expected==1?0x00e:expected==2?0x0e0:0,kSceneRGB888,r,g,b,error),"declared source color");size_t at=(y*256+x)*3;check(image.rgb[at]==r&&image.rgb[at+1]==g&&image.rgb[at+2]==b,"canonical complete frame colors");}check(image.spriteLimitReached==(index<6||index>=8),"row budget diagnostic reflects actual truncation");}
 SceneRenderer partial;SceneLayout layout;layout.width=256;layout.height=224;layout.columns=layout.rows=32;layout.planeEnabled[0]=layout.planeEnabled[1]=false;check(partial.configure(layout,error)&&partial.setPalette(std::vector<uint16_t>(64,0),0,error),"partial pattern owner fixture");GraphicsTransfer tile;tile.destination=32;tile.decoded.assign(32,0x11);check(partial.applyTransfer(tile,error),"only fetched pattern is established");std::vector<PlacedPiece> pieces(16,PlacedPiece(0,64,8,8,1));pieces.push_back(PlacedPiece(160,64,8,8,2047));SceneImage image;check(partial.render(pieces,kSceneRGB888,image,error),"unselected seventeenth piece does not fetch unknown patterns");pieces={PlacedPiece(-80,64,8,8,1),PlacedPiece(-128,64,8,8,2047),PlacedPiece(80,64,8,8,2047)};check(partial.render(pieces,kSceneRGB888,image,error),"zero marker and masked successor do not fetch patterns");
 std::printf("sprite rows: %u checks passed\n",checks);return 0;}catch(const std::exception& e){std::fprintf(stderr,"sprite row failure after %u checks: %s\n",checks,e.what());return 1;}}
